// =============================================================================
// REGISTRY -- kubejs/server_scripts/0_lib_registry.js (icraft.bosses, icraft.dims)
// on the production engine, against dev/rosters/rosters.py.
//
// T_REG is generated by run.py from rosters.py for the registry files of the pack
// under test: for every system the ids in file order and the value each id gets.
// The reader has to give exactly that, id by id: so the proof table of
// dev/rosters/table.py (old script lists == rosters.py) also holds for what a
// script is answered in game. Then the reader's own rules: ids are normalised
// and a second id of a boss (`sameAs`) answers as that boss and is in no list
// (a Java string works), what it hands out is a copy, an unknown system throws,
// and a registry that cannot be read is an error on every call, never an empty
// roster.
// =============================================================================
;(function () {
  var same = function (a, b) { return JSON.stringify(a) === JSON.stringify(b) }
  var bosses = function () { return global.icraft.bosses }
  var dims = function () { return global.icraft.dims }
  var throwsWith = function (fn, needle) {
    try { fn(); return 'no throw' } catch (e) { return String(e).indexOf(needle) >= 0 ? '' : 'threw something else: ' + e }
  }

  T_run('the reader loaded both files and prints the validator\'s line', function () {
    ok(T_LOAD_ERRORS.length === 0, 'the three scripts load (' + T_LOAD_ERRORS.join('; ') + ')')
    ok(global.icraft.registry.ok() === true, 'registry.ok() (' + global.icraft.registry.problems().join('; ') + ')')
    ok(String(global.icraft.registry.line()) === T_REG.bootLine, 'the boot line is the one rosters.py computes: ' + global.icraft.registry.line())
    ok(T_LOG.info.indexOf(T_REG.bootLine) >= 0, 'and it was printed with console.log, once')
    ok(T_LOG.error.length === 0, 'no console.error while loading (' + T_LOG.error.join(' | ') + ')')
    ok(same(global.icraft.registry.systems('bosses'), T_REG.bossSystems), 'the boss systems are those of rosters.py, in order')
    ok(same(global.icraft.registry.systems('dims'), T_REG.dimSystems), 'the dimension systems are those of rosters.py, in order')
  })

  // one check per system: ids(system) in order; has / get for every id of the registry
  var perSystem = function (what, api, systems, allIds, cells) {
    for (var s = 0; s < systems.length; s++) {
      var system = systems[s]
      var want = cells[system]            // [[id, value], ...] in file order
      var wantIds = []
      var wantValue = {}
      var bad = ''
      for (var w = 0; w < want.length; w++) { wantIds.push(want[w][0]); wantValue[want[w][0]] = want[w][1] }
      if (!same(api.ids(system), wantIds)) bad = 'ids(' + system + ') is ' + JSON.stringify(api.ids(system)).substring(0, 200)
      for (var i = 0; i < allIds.length && bad === ''; i++) {
        var id = allIds[i]
        var inIt = Object.prototype.hasOwnProperty.call(wantValue, id)
        if (api.has(id, system) !== inIt) bad = 'has(' + id + ', ' + system + ') is ' + api.has(id, system)
        else if (inIt && !same(api.get(id, system), wantValue[id])) bad = 'get(' + id + ', ' + system + ') is ' + JSON.stringify(api.get(id, system))
        else if (!inIt && api.get(id, system) !== null) bad = 'get(' + id + ', ' + system + ') is not null'
      }
      ok(bad === '', what + ' system ' + system + ': ' + wantIds.length + ' ids, every id of the registry asked' + (bad === '' ? '' : ' -- ' + bad))
    }
  }

  T_run('bosses: every id against every system, as rosters.py has it', function () {
    ok(same(bosses().ids(), T_REG.bossIds), 'ids() is the file order (' + T_REG.bossIds.length + ' entries)')
    perSystem('boss', bosses(), T_REG.bossSystems, T_REG.bossIds, T_REG.bossCells)
    var bad = ''
    for (var i = 0; i < T_REG.bossIds.length && bad === ''; i++) {
      var id = T_REG.bossIds[i]
      if (bosses().tier(id) !== T_REG.bossTier[id]) bad = 'tier(' + id + ') = ' + bosses().tier(id)
      else if (bosses().kind(id) !== T_REG.bossKind[id]) bad = 'kind(' + id + ') = ' + bosses().kind(id)
      else if (bosses().is(id) !== bosses().has(id, 'isBoss')) bad = 'is(' + id + ') differs from has(.., isBoss)'
      else if (bosses().hp(id) !== bosses().get(id, 'hp')) bad = 'hp(' + id + ') differs from get(.., hp)'
    }
    ok(bad === '', 'tier / kind / is / hp of every id' + (bad === '' ? '' : ' -- ' + bad))
    bad = ''
    for (var t = 0; t <= 5; t++) {
      var want = []
      var wantRush = []
      for (var j = 0; j < T_REG.bossIds.length; j++) {
        if (T_REG.bossTier[T_REG.bossIds[j]] === t && t !== 0) {
          want.push(T_REG.bossIds[j])
          if (bosses().has(T_REG.bossIds[j], 'rush')) wantRush.push(T_REG.bossIds[j])
        }
      }
      if (!same(bosses().byTier(t), want)) bad = 'byTier(' + t + ')'
      if (!same(bosses().byTier(t, 'rush'), wantRush)) bad = 'byTier(' + t + ', rush)'
    }
    ok(bad === '', 'byTier(n) and byTier(n, system) for n = 0..5' + (bad === '' ? '' : ' -- ' + bad))
    var arenas = bosses().arenas()
    var wantKeys = []
    var wantArenas = {}
    for (var a = 0; a < T_REG.arenas.length; a++) { wantKeys.push(T_REG.arenas[a][0]); wantArenas[T_REG.arenas[a][0]] = T_REG.arenas[a][1] }
    ok(same(Object.keys(arenas), wantKeys), 'arenas(): ' + wantKeys.length + ' keys in file order')
    ok(same(arenas, wantArenas), 'arenas(): every record, without its key')
    ok(bosses().enabled('perKill') === T_REG.perKill, 'enabled(perKill) is the switch of the file: ' + T_REG.perKill)
  })

  T_run('dimensions: every id against every system, as rosters.py has it', function () {
    ok(same(dims().ids(), T_REG.dimIds), 'ids() is the file order (' + T_REG.dimIds.length + ' entries)')
    perSystem('dimension', dims(), T_REG.dimSystems, T_REG.dimIds, T_REG.dimCells)
    var bad = ''
    for (var i = 0; i < T_REG.dimIds.length && bad === ''; i++) {
      if (dims().tier(T_REG.dimIds[i]) !== T_REG.dimTier[T_REG.dimIds[i]]) bad = 'tier(' + T_REG.dimIds[i] + ')'
    }
    ok(bad === '', 'tier of every id' + (bad === '' ? '' : ' -- ' + bad))
    bad = ''
    var all = []
    for (var t = 1; t <= 4; t++) {
      var want = []
      var wantLoot = []
      for (var j = 0; j < T_REG.dimIds.length; j++) {
        if (T_REG.dimTier[T_REG.dimIds[j]] === t) {
          want.push(T_REG.dimIds[j])
          if (dims().has(T_REG.dimIds[j], 'loot')) wantLoot.push(T_REG.dimIds[j])
        }
      }
      if (!same(dims().inTier(t), want)) bad = 'inTier(' + t + ')'
      if (!same(dims().inTier(t, 'loot'), wantLoot)) bad = 'inTier(' + t + ', loot)'
      all = all.concat(wantLoot)
    }
    ok(bad === '', 'inTier(n) and inTier(n, system) for n = 1..4' + (bad === '' ? '' : ' -- ' + bad))
    ok(same(dims().inTiers([1, 2, 3, 4], 'loot'), all), 'inTiers([1, 2, 3, 4], loot) is the four groups joined, in tier order')
    ok(same(dims().inTiers([2, 1], 'loot'), dims().inTier(2, 'loot').concat(dims().inTier(1, 'loot'))), 'inTiers keeps the order it is asked in')
    ok(same(dims().inTier(9), []) && same(dims().inTiers([], 'loot'), []), 'a tier nothing is in, and no tiers: an empty list')
  })

  T_run('an id is normalised: a String from Java is answered like a JS string', function () {
    var raw = __host.javaString(T_REG.aBoss)          // what entity.type hands a script
    ok(typeof raw === 'object', 'the test id is a Java string (typeof ' + (typeof raw) + ')')
    ok(new Set([T_REG.aBoss]).has(raw) === false, 'which a Set does not match (the trap the per-kill scaling sat in)')
    ok(bosses().is(raw) === true && bosses().has(raw, 'isBoss') === true, 'bosses.is / has accept it')
    ok(bosses().tier(raw) === T_REG.bossTier[T_REG.aBoss] && bosses().kind(raw) === T_REG.bossKind[T_REG.aBoss], 'bosses.tier / kind accept it')
    var rawDim = __host.javaString(T_REG.aDim)
    ok(dims().tier(rawDim) === T_REG.dimTier[T_REG.aDim] && dims().has(rawDim, 'loot') === dims().has(T_REG.aDim, 'loot'), 'dims.tier / has accept it')
  })

  T_run('an id with no entry, and a system that does not exist', function () {
    var none = 'minecraft:zombie'
    ok(bosses().is(none) === false && bosses().has(none, 'x3') === false && bosses().get(none, 'x3') === null, 'no entry: is / has false, get null')
    ok(bosses().tier(none) === 0 && bosses().hp(none) === null && bosses().kind(none) === '', 'no entry: tier 0, hp null, kind empty')
    ok(dims().tier('minecraft:nowhere') === 0 && dims().has('minecraft:nowhere', 'loot') === false, 'no dimension entry: tier 0, has false')
    ok(bosses().is('toString') === false && bosses().has('constructor', 'hp') === false && bosses().tier('__proto__') === 0, 'a name every object has is not an entry')
    ok(bosses().is(null) === false && bosses().is(undefined) === false && bosses().tier('') === 0, 'null / undefined / empty: not a boss, no throw')
    ok(throwsWith(function () { bosses().has(T_REG.aBoss, 'x33') }, 'is not a boss system') === '', 'bosses.has with a misspelt system THROWS')
    ok(throwsWith(function () { bosses().get(T_REG.aBoss, 'hP') }, 'is not a boss system') === '', 'bosses.get with a misspelt system THROWS')
    ok(throwsWith(function () { bosses().ids('nope') }, 'is not a boss system') === '', 'bosses.ids with a misspelt system THROWS')
    ok(throwsWith(function () { bosses().byTier(2, 'nope') }, 'is not a boss system') === '', 'bosses.byTier with a misspelt system THROWS')
    ok(throwsWith(function () { dims().has(T_REG.aDim, 'Loot') }, 'is not a dimension system') === '', 'dims.has with a misspelt system THROWS')
    ok(throwsWith(function () { dims().inTier(2, 'lot') }, 'is not a dimension system') === '', 'dims.inTier with a misspelt system THROWS')
    ok(throwsWith(function () { bosses().enabled('perkill') }, 'is not a switch') === '', 'bosses.enabled with a misspelt switch THROWS')
  })

  T_run('what the reader hands out is a copy', function () {
    var arenaBoss = bosses().ids('arena')[0]
    var a = bosses().get(arenaBoss, 'arena')
    a.display = 'CHANGED'
    a.locator = 'summon'
    ok(bosses().get(arenaBoss, 'arena').display !== 'CHANGED' && bosses().get(arenaBoss, 'arena').locator !== 'summon', 'get(.., arena): changing the record changes nothing')
    var all = bosses().arenas()
    var firstKey = Object.keys(all)[0]
    all[firstKey].tier = 99
    delete all[Object.keys(all)[1]]
    ok(bosses().arenas()[firstKey].tier !== 99 && Object.keys(bosses().arenas()).length === T_REG.arenas.length, 'arenas(): a fresh table each call')
    var ids = bosses().ids('x3')
    ids.push('minecraft:zombie')
    ok(bosses().ids('x3').indexOf('minecraft:zombie') < 0 && bosses().has('minecraft:zombie', 'x3') === false, 'ids(system): changing the list changes nothing')
    var equipDim = dims().ids('mobEquipment')[0]
    var cfg = dims().get(equipDim, 'mobEquipment')
    cfg.weapons.push('minecraft:stick')
    ok(dims().get(equipDim, 'mobEquipment').weapons.indexOf('minecraft:stick') < 0, 'get(.., mobEquipment): changing the config changes nothing')
    var tier2 = dims().inTier(2, 'loot')
    tier2.length = 0
    ok(dims().inTier(2, 'loot').length > 0, 'inTier: changing the list changes nothing')
  })

  // ---- a registry that cannot be read ---------------------------------------
  // The reader is loaded again with a JsonIO that serves a changed bosses.json /
  // dimensions.json (null = the file does not exist, as the engine answers).
  var realJsonIO = JsonIO
  var realText = { bosses: String(JsonIO.readString('kubejs/config/icraft/registry/bosses.json')), dims: String(JsonIO.readString('kubejs/config/icraft/registry/dimensions.json')) }
  var reload = function (bossText, dimText) {
    JsonIO = {
      readString: function (path) {
        var p = String(path)
        if (p.indexOf('bosses.json') >= 0) { if (bossText === 'THROW') throw new Error('disk on fire'); return bossText }
        if (p.indexOf('dimensions.json') >= 0) return dimText
        return realJsonIO.readString(path)
      }
    }
    T_LOG.error.length = 0
    T_LOG.info.length = 0
    var err = String(__host.load(T_REG.readerPath))
    JsonIO = realJsonIO
    return err
  }
  var changed = function (text, fn) { var d = JSON.parse(text); fn(d); return JSON.stringify(d) }
  var refused = function (what, bossText, dimText, wantInError, which) {
    var err = reload(bossText, dimText)
    var line = T_LOG.error.join(' | ')
    var api = which === 'dims' ? dims() : bosses()
    var other = which === 'dims' ? bosses() : dims()
    var call = throwsWith(function () { if (which === 'dims') api.tier(T_REG.aDim); else api.is(T_REG.aBoss) }, 'is not loaded')
    var otherOk = true
    try { if (which === 'dims') other.is(T_REG.aBoss); else other.tier(T_REG.aDim) } catch (e) { otherOk = false }
    ok(err === '' && global.icraft.registry.ok() === false && line.indexOf('[icraft.registry] NOT LOADED') >= 0 &&
      line.indexOf(wantInError) >= 0 && call === '' && otherOk && T_LOG.info.join('|').indexOf('[icraft.registry] loaded') < 0,
      what + ': one ERROR line that says why, every call THROWS, the other file still answers, no "loaded" line' +
      ' (load: "' + err + '", call: "' + call + '", other file ok: ' + otherOk + ', error line: ' + line.substring(0, 160) + ')')
  }

  T_run('a registry that cannot be read is an error on every call, never an empty roster', function () {
    refused('bosses.json does not exist', null, realText.dims, 'does not exist', 'bosses')
    ok(throwsWith(function () { bosses().has(T_REG.aBoss, 'x3') }, 'not an empty boss roster') === '' &&
      throwsWith(function () { bosses().ids('rush') }, 'not an empty boss roster') === '' &&
      throwsWith(function () { bosses().arenas() }, 'not an empty boss roster') === '' &&
      throwsWith(function () { bosses().byTier(1) }, 'not an empty boss roster') === '' &&
      throwsWith(function () { bosses().hp(T_REG.aBoss) }, 'not an empty boss roster') === '' &&
      throwsWith(function () { bosses().enabled('perKill') }, 'not an empty boss roster') === '', 'has / ids / arenas / byTier / hp / enabled all throw, and say it is not an empty roster')
    refused('bosses.json cannot be read (JsonIO throws)', 'THROW', realText.dims, 'could not be read', 'bosses')
    refused('bosses.json is not JSON', '{ "schema": 1, "bosses": {', realText.dims, 'is not JSON', 'bosses')
    refused('bosses.json has another schema', changed(realText.bosses, function (d) { d.schema = 2 }), realText.dims, 'schema 2', 'bosses')
    refused('bosses.json has no bosses object', changed(realText.bosses, function (d) { delete d.bosses }), realText.dims, 'no "bosses" object', 'bosses')
    refused('an entry with a misspelt key', changed(realText.bosses, function (d) { var e = d.bosses[T_REG.aBoss]; e.flag = e.flags; delete e.flags }), realText.dims, 'unknown key "flag"', 'bosses')
    refused('an entry with a misspelt flag', changed(realText.bosses, function (d) { d.bosses[T_REG.aBoss].flags.push('X3') }), realText.dims, 'unknown flag "X3"', 'bosses')
    refused('an entry with a kind that does not exist', changed(realText.bosses, function (d) { d.bosses[T_REG.aBoss].kind = 'boss' }), realText.dims, 'kind "boss"', 'bosses')
    refused('an entry without a tier', changed(realText.bosses, function (d) { delete d.bosses[T_REG.aBoss].tier }), realText.dims, 'no tier', 'bosses')
    refused('a rush roster that does not exist', changed(realText.bosses, function (d) { d.bosses[T_REG.aBoss].rush = 4 }), realText.dims, 'rush 4', 'bosses')
    refused('a switch that does not exist', changed(realText.bosses, function (d) { d.switches.perKil = { on: true } }), realText.dims, 'unknown switch', 'bosses')
    refused('dimensions.json does not exist', realText.bosses, null, 'does not exist', 'dims')
    ok(throwsWith(function () { dims().inTier(2, 'loot') }, 'not an empty dimension list') === '' &&
      throwsWith(function () { dims().has(T_REG.aDim, 'loot') }, 'not an empty dimension list') === '' &&
      throwsWith(function () { dims().ids() }, 'not an empty dimension list') === '', 'inTier / has / ids all throw, and say it is not an empty list')
    refused('a dimension with a misspelt key', realText.bosses, changed(realText.dims, function (d) { d.dimensions[T_REG.aDim].deathPenalti = 0.2 }), 'unknown key "deathPenalti"', 'dims')
    refused('a dimension with a tier that does not exist', realText.bosses, changed(realText.dims, function (d) { d.dimensions[T_REG.aDim].tier = 5 }), 'tier 5', 'dims')
    var err = reload(realText.bosses, realText.dims)
    ok(err === '' && global.icraft.registry.ok() === true && bosses().is(T_REG.aBoss) === true && T_LOG.error.length === 0 &&
      T_LOG.info.indexOf(T_REG.bootLine) >= 0, 'the real files again: loaded, answers, the boot line, no error')
  })

  // ---- second ids (`sameAs`) -------------------------------------------------
  // The game hands scripts some bosses under a second entity id (the Wither a
  // player fights is progressivebosses:wither, never minecraft:wither). The file
  // may hold none, so the rules are tested on a planted one first, then on
  // whatever the pack's file holds.
  T_run('a second id (sameAs) answers as the boss it is, and is in no list', function () {
    var boss = T_REG.aBoss
    var second = 'test:second_id'
    var withSecond = changed(realText.bosses, function (d) { d.bosses[second] = { sameAs: boss, note: 'planted by the suite' } })
    var err = reload(withSecond, realText.dims)
    ok(err === '' && global.icraft.registry.ok() === true && T_LOG.error.length === 0, 'the file with a planted second id loads (' + err + T_LOG.error.join(' | ') + ')')
    ok(bosses().canon(second) === boss && bosses().canon(boss) === boss && bosses().canon('minecraft:zombie') === 'minecraft:zombie',
      'canon: the second id is the boss, the boss is itself, an id with no entry is itself')
    ok(bosses().canon(__host.javaString(second)) === boss && typeof bosses().canon(__host.javaString(second)) === 'string', 'canon takes a Java string and hands back a JS string')
    var bad = ''
    for (var s = 0; s < T_REG.bossSystems.length && bad === ''; s++) {
      var system = T_REG.bossSystems[s]
      if (bosses().has(second, system) !== bosses().has(boss, system)) bad = 'has(.., ' + system + ')'
      else if (!same(bosses().get(second, system), bosses().get(boss, system))) bad = 'get(.., ' + system + ')'
    }
    ok(bad === '', 'has / get of the second id are those of the boss, for all ' + T_REG.bossSystems.length + ' systems' + (bad === '' ? '' : ' -- ' + bad))
    ok(bosses().is(second) === true && bosses().tier(second) === bosses().tier(boss) && bosses().kind(second) === bosses().kind(boss) &&
      bosses().hp(second) === bosses().hp(boss) && bosses().is(__host.javaString(second)) === true, 'is / tier / kind / hp too, and with a Java string')
    ok(global.icraft.core.isBoss(second) === true && global.icraft.core.isBoss(T_mob(second)) === true, 'core.isBoss: the id and the entity')
    bad = ''
    if (!same(bosses().ids(), T_REG.bossIds)) bad = 'ids()'
    for (var s2 = 0; s2 < T_REG.bossSystems.length && bad === ''; s2++) {
      if (bosses().ids(T_REG.bossSystems[s2]).indexOf(second) >= 0) bad = 'ids(' + T_REG.bossSystems[s2] + ')'
    }
    for (var t = 1; t <= 4 && bad === ''; t++) { if (bosses().byTier(t).indexOf(second) >= 0) bad = 'byTier(' + t + ')' }
    ok(bad === '', 'no list holds it: ids() is the ' + T_REG.bossIds.length + ' bosses, ids(system) and byTier(n) unchanged' + (bad === '' ? '' : ' -- ' + bad))
    ok(same(bosses().entityIds(boss), [boss, second]) && same(bosses().entityIds(second), [boss, second]) &&
      same(bosses().entityIds('minecraft:zombie'), ['minecraft:zombie']), 'entityIds: [boss, second id] asked either way; an id with no entry comes back alone')
    var list = bosses().entityIds(boss)
    list.push('minecraft:zombie')
    ok(bosses().entityIds(boss).length === 2, 'entityIds hands out a fresh list')
    var planted = T_REG.aliases.length + 1       // the file's own second ids, and the planted one
    ok(String(global.icraft.registry.line()).indexOf(', ' + planted + ' second id' + (planted === 1 ? '' : 's') + ';') > 0 &&
      String(global.icraft.registry.line()).indexOf('bosses: ' + T_REG.bossIds.length + ' entries') > 0,
      'the boot line counts it apart (' + planted + '): the number of entries is the number of bosses')
    refused('a second id that names no entry', changed(realText.bosses, function (d) { d.bosses[second] = { sameAs: 'test:nobody' } }), realText.dims, 'sameAs names no other entry', 'bosses')
    refused('a second id that names itself', changed(realText.bosses, function (d) { d.bosses[second] = { sameAs: second } }), realText.dims, 'sameAs names no other entry', 'bosses')
    refused('a second id that names a second id', changed(withSecond, function (d) { d.bosses['test:third_id'] = { sameAs: second } }), realText.dims, 'itself a second id', 'bosses')
    refused('a second id with flags of its own', changed(realText.bosses, function (d) { d.bosses[second] = { sameAs: boss, flags: ['x3'] } }), realText.dims, 'unknown key "flags"', 'bosses')
    refused('a second id with a tier of its own', changed(realText.bosses, function (d) { d.bosses[second] = { sameAs: boss, tier: 2 } }), realText.dims, 'unknown key "tier"', 'bosses')
    refused('a phase credited to a second id', changed(withSecond, function (d) { d.bosses['test:phase'] = { tier: 1, kind: 'unlisted', phaseOf: second } }), realText.dims, 'phaseOf names no entry', 'bosses')
    err = reload(realText.bosses, realText.dims)
    ok(err === '' && global.icraft.registry.ok() === true && bosses().canon(second) === second && bosses().is(second) === false, 'the real file again: the planted id is nobody')
    // the pack's own second ids, as rosters.py reads them
    bad = ''
    for (var a = 0; a < T_REG.aliases.length && bad === ''; a++) {
      var al = T_REG.aliases[a][0]
      var of = T_REG.aliases[a][1]
      if (bosses().canon(al) !== of) bad = 'canon(' + al + ') = ' + bosses().canon(al)
      else if (bosses().ids().indexOf(al) >= 0) bad = al + ' is in ids()'
      else if (bosses().is(al) !== bosses().is(of) || bosses().tier(al) !== bosses().tier(of) || bosses().kind(al) !== bosses().kind(of) || bosses().hp(al) !== bosses().hp(of)) bad = al + ' does not answer as ' + of
      for (var s3 = 0; s3 < T_REG.bossSystems.length && bad === ''; s3++) {
        if (!same(bosses().get(al, T_REG.bossSystems[s3]), bosses().get(of, T_REG.bossSystems[s3]))) bad = 'get(' + al + ', ' + T_REG.bossSystems[s3] + ')'
      }
    }
    for (var e = 0; e < T_REG.entityIds.length && bad === ''; e++) {
      if (!same(bosses().entityIds(T_REG.entityIds[e][0]), T_REG.entityIds[e][1])) bad = 'entityIds(' + T_REG.entityIds[e][0] + ') = ' + JSON.stringify(bosses().entityIds(T_REG.entityIds[e][0]))
    }
    ok(bad === '', 'the ' + T_REG.aliases.length + ' second id(s) of the pack\'s file answer as rosters.py has them' + (bad === '' ? '' : ' -- ' + bad))
  })

  // ---- a boss under another type (`seenAs`) ---------------------------------
  // Iron's Spellbooks' Magehunter is created with the type minecraft:vindicator and
  // saved under it: in play it is a plain Vindicator. The entry says how to tell it
  // apart (its Java class, or its marks: base health + the item in its main hand);
  // core.entityId recognises it and stamps it. The class path cannot be built on a
  // mock (a mock's class is the mock's): it is measured on the full pack (internal
  // dev/rulings-combat-2026-10-14/). Here: the record, the refusals, the marks, the stamp.
  T_run('a boss under another type (seenAs): the record, the refusals, the marks and the stamp', function () {
    var core = global.icraft.core
    ok(same(bosses().seenAs(), T_REG.seenAs), 'seenAs() is what rosters.py reads (' + T_REG.seenAs.length + ' entr' + (T_REG.seenAs.length === 1 ? 'y' : 'ies') + ')')
    var copyList = bosses().seenAs()
    if (copyList.length > 0) { copyList[0].type = 'test:changed'; copyList.push({}) }
    ok(same(bosses().seenAs(), T_REG.seenAs), 'it hands out a fresh copy')
    var boss = 'test:seen_boss'
    var planted = changed(realText.bosses, function (d) {
      d.bosses[boss] = { tier: 2, kind: 'unlisted', flags: ['boss'], seenAs: { type: 'test:plain_mob', baseHealth: 50, mainHand: 'test:marker_sword' }, note: 'planted by the suite' }
    })
    var err = reload(planted, realText.dims)
    ok(err === '' && global.icraft.registry.ok() === true && T_LOG.error.length === 0, 'a file with a planted seenAs entry loads (' + err + T_LOG.error.join(' | ') + ')')
    var marked = function (base, held) {
      var m = T_mob('test:plain_mob')
      if (base !== null) T.get(m, 'attrBase').put('minecraft:generic.max_health', base)
      if (held !== null) m.setItemSlot(MSlot.MAINHAND, new MStack(held, 1))
      return m
    }
    var plain = marked(null, null)
    ok(core.entityId(plain) === 'test:plain_mob' && core.seenAsId(plain) === '' && core.isBoss(plain) === false, 'a mob of that type without the marks: its own type, not a boss')
    ok(core.entityId(marked(50, null)) === 'test:plain_mob' && core.entityId(marked(24, 'test:marker_sword')) === 'test:plain_mob',
      'one mark alone is not enough (base health 50 without the item; the item on base health 24)')
    var it = marked(50, 'test:marker_sword')
    ok(core.entityId(it) === boss && core.seenAsId(it) === boss && core.isBoss(it) === true, 'both marks: core.entityId and seenAsId answer the boss id, core.isBoss is true')
    ok(String(it.persistentData.getString('icraft_entity_id')) === boss, 'and it is stamped (persistentData icraft_entity_id)')
    it.setItemSlot(MSlot.MAINHAND, new MStack('minecraft:air', 0))
    ok(core.entityId(it) === boss, 'the stamp holds when the marks are gone (the sword taken from its hand)')
    var reloaded = marked(null, null)
    reloaded.persistentData.putString('icraft_entity_id', boss)
    ok(core.entityId(reloaded) === boss && core.isBoss(reloaded) === true, 'a mob of that type that carries only the stamp (as after a save and load) is the boss')
    var other = T_mob('minecraft:zombie')
    other.persistentData.putString('icraft_entity_id', boss)
    ok(core.entityId(other) === 'minecraft:zombie', 'a stamp on a mob of ANOTHER type is not read')
    ok(core.entityId(T_mob('minecraft:zombie')) === 'minecraft:zombie' && core.seenAsId(null) === '' && core.entityId(null) === '', 'any other type, and nothing, as before')
    var refusedSeen = function (what, fn, needle) { refused(what, changed(planted, function (d) { fn(d.bosses[boss].seenAs, d) }), realText.dims, needle, 'bosses') }
    refusedSeen('a seenAs with an unknown key', function (sa) { sa.colour = 'red' }, 'seenAs has an unknown key "colour"')
    refusedSeen('a seenAs whose type is its own id', function (sa) { sa.type = boss }, 'seenAs needs the entity `type`')
    refusedSeen('a seenAs whose type has an entry of its own', function (sa) { sa.type = T_REG.aBoss }, 'has an entry of its own')
    refusedSeen('a seenAs with one mark only', function (sa) { delete sa.mainHand }, 'marks need both baseHealth')
    refusedSeen('a seenAs with neither class nor marks', function (sa) { delete sa.mainHand; delete sa.baseHealth }, 'needs a class, or marks')
    refusedSeen('two entries seen as one type', function (sa, d) { d.bosses['test:seen_twice'] = { tier: 2, kind: 'unlisted', seenAs: { type: 'test:plain_mob', 'class': 'x.Y' } } }, 'is already the type of')
    err = reload(realText.bosses, realText.dims)
    ok(err === '' && global.icraft.registry.ok() === true && T_LOG.error.length === 0, 'the real file again')
  })

  T_run('a switch is read from the file', function () {
    reload(changed(realText.bosses, function (d) { d.switches.perKill.on = true }), realText.dims)
    ok(bosses().enabled('perKill') === true && String(global.icraft.registry.line()).indexOf('per-kill scaling ON') > 0, 'perKill on in the file: enabled() true and the boot line says ON')
    reload(changed(realText.bosses, function (d) { delete d.switches }), realText.dims)
    ok(bosses().enabled('perKill') === false, 'no switches object: off')
    reload(realText.bosses, realText.dims)
    ok(bosses().enabled('perKill') === T_REG.perKill, 'the real file again')
  })

  T_run('core.isBoss asks the registry', function () {
    var core = global.icraft.core
    var mob = T_mob(T_REG.aBoss)
    ok(core.isBoss(T_REG.aBoss) === true && core.isBoss(__host.javaString(T_REG.aBoss)) === true && core.isBoss(mob) === true, 'true for a boss: a JS string, a Java string, the entity')
    ok(core.isBoss('minecraft:zombie') === false && core.isBoss(T_mob('minecraft:zombie')) === false && core.isBoss(null) === false, 'false for a zombie and for nothing')
    var bad = ''
    for (var i = 0; i < T_REG.bossIds.length && bad === ''; i++) {
      if (core.isBoss(T_REG.bossIds[i]) !== bosses().has(T_REG.bossIds[i], 'isBoss')) bad = T_REG.bossIds[i]
    }
    ok(bad === '', 'the same answer as the registry for every id' + (bad === '' ? '' : ' -- ' + bad))
    reload(null, realText.dims)
    ok(throwsWith(function () { core.isBoss(T_REG.aBoss) }, 'is not loaded') === '', 'with no registry core.isBoss THROWS: "nobody is a boss" is never the answer to a missing file')
    reload(realText.bosses, realText.dims)
    ok(core.isBoss(T_REG.aBoss) === true, 'the real file again')
  })
})()
